+    available: false,
+    reason: "census unavailable: CI runner has no hub census",
+    agents: [],
+    busy_sia: [],
+    samples: 0,
+  },
+  vitest: { passed: null, failed: null, errors: null, exit_code: null },
+  ci: {
+    runner_name: runnerName,
+    runner_labels: labels,
+    timestamp,
+    concurrent_jobs: concurrent,
+  },
